  letter-spacing: var(--typography-label-md-strong-letter-spacing);
}
.bcn-atl {
  --atl-day: 4px;
  --atl-label: 320px;
  --atl-row: 48px;
  --atl-head: 32px;
  --atl-mark-size: 10px;
  --atl-line: var(--color-border-default-subtle);
}
.bcn-atl[hidden],
.bcn-atl [hidden] {
  display: none;
}
.bcn-atl__module {
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-100);
  background: var(--color-background-elevation-raised);
  color: var(--color-content-default);
  font-size: 14px;
}
.bcn-atl__scroll {
  border-radius: var(--radius-100);
  max-height: max(26rem, 100vh - 14rem);
  overflow: auto;
}
.bcn-atl__scroll:focus-visible {
  outline: var(--focus-ring-width, 2px) solid
    var(--focus-ring-color, var(--color-border-default-focus));
  outline-offset: -2px;
}
.bcn-atl__canvas {
  width: calc(var(--atl-label) + var(--atl-days, 0) * var(--atl-day));
  position: relative;
}
.bcn-atl__head {
  z-index: 5;
  grid-template-columns: var(--atl-label) calc(var(--atl-days, 0) * var(--atl-day));
  height: var(--atl-head);
  background: var(--color-background-default);
  border-bottom: 1px solid var(--color-border-default);
  display: grid;
  position: sticky;
  top: 0;
}
.bcn-atl__corner {
  z-index: 6;
  padding: 0 var(--spacing-300);
  background: var(--color-background-default);
  border-right: 1px solid var(--color-border-default);
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default-secondary);
  align-items: center;
  display: flex;
  position: sticky;
  left: 0;
}
.bcn-atl__axis {
  position: relative;
}
.bcn-atl__month {
  top: 0;
  bottom: 0;
  left: calc(var(--x) * var(--atl-day));
  width: calc(var(--span) * var(--atl-day));
  border-left: 1px solid var(--color-border-default);
  align-items: center;
  display: flex;
  position: absolute;
}
.bcn-atl__month-name {
  padding: 0 var(--spacing-200);
  font-size: 13px;
  font-weight: var(--typography-font-weight-semibold);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
  color: var(--color-content-default-secondary);
}
.bcn-atl__today-flag {
  bottom: 0;
  left: calc(var(--atl-today, 0) * var(--atl-day));
  z-index: 1;
  padding: 0 var(--spacing-150);
  border-radius: var(--radius-100) var(--radius-100) 0 0;
  background: var(--color-background-utility-info);
  color: var(--color-content-default-knockout);
  font-size: 13px;
  font-weight: var(--typography-font-weight-semibold);
  white-space: nowrap;
  line-height: 1.5;
  position: absolute;
  transform: translate(-50%);
}
.bcn-atl__body {
  position: relative;
}
.bcn-atl__grid {
  inset: 0 0 0 var(--atl-label);
  pointer-events: none;
  position: absolute;
}
.bcn-atl__rule {
  top: 0;
  bottom: 0;
  left: calc(var(--x) * var(--atl-day));
  background: var(--atl-line);
  width: 1px;
  position: absolute;
}
.bcn-atl__today {
  top: 0;
  bottom: 0;
  left: calc(var(--atl-today, 0) * var(--atl-day) - 1px);
  z-index: 1;
  background: var(--color-background-utility-info);
  width: 2px;
  position: absolute;
}
.bcn-atl__ghead {
  z-index: 4;
  cursor: pointer;
  background: var(--color-background-default);
  border-bottom: 1px solid var(--color-border-default);
  align-items: center;
  height: 36px;
  list-style: none;
  display: flex;
  position: relative;
}
.bcn-atl__ghead::-webkit-details-marker {
  display: none;
}
.bcn-atl__group + .bcn-atl__group .bcn-atl__ghead {
  border-top: 1px solid var(--color-border-default);
}
.bcn-atl__ghead:focus-visible {
  outline: var(--focus-ring-width, 2px) solid
    var(--focus-ring-color, var(--color-border-default-focus));
  outline-offset: -2px;
}
.bcn-atl__ghead-text {
  align-items: center;
  gap: var(--spacing-200);
  padding: 0 var(--spacing-300);
  white-space: nowrap;
  display: inline-flex;
  position: sticky;
  left: 0;
}
.bcn-atl__chevron {
  color: var(--color-content-default-secondary);
  transition: transform 0.12s;
  display: inline-flex;
}
.bcn-atl__group[open] > .bcn-atl__ghead .bcn-atl__chevron {
  transform: rotate(90deg);
}
.bcn-atl__swatch {
  width: var(--atl-mark-size);
  height: var(--atl-mark-size);
  border-radius: var(--radius-full);
  background: var(--atl-tone);
}
.bcn-atl__glabel {
  font-weight: var(--typography-font-weight-semibold);
}
.bcn-atl__gcount {
  font-variant-numeric: tabular-nums;
  color: var(--color-content-default-secondary);
}
.bcn-atl__row {
  grid-template-columns: var(--atl-label) calc(var(--atl-days, 0) * var(--atl-day));
  height: var(--atl-row);
  border-bottom: 1px solid var(--atl-line);
  cursor: pointer;
  display: grid;
  position: relative;
}
.bcn-atl__row:hover .bcn-atl__label,
.bcn-atl__row:hover .bcn-atl__track {
  background: color-mix(
    in srgb,
    var(--color-background-default-hover) 45%,
    var(--color-background-elevation-raised)
  );
}
.bcn-atl__label {
  z-index: 3;
  min-width: 0;
  padding: 0 var(--spacing-300);
  background: var(--color-background-elevation-raised);
  border-right: 1px solid var(--color-border-default);
  flex-direction: column;
  justify-content: center;
  gap: 2px;
  display: flex;
  position: sticky;
  left: 0;
}
.bcn-atl__name {
  text-overflow: ellipsis;
  white-space: nowrap;
  font-weight: var(--typography-font-weight-medium);
  color: var(--color-content-default);
  text-decoration: none;
  overflow: hidden;
}
.bcn-atl__name:hover {
  text-decoration: underline;
}
.bcn-atl__name:focus-visible {
  outline: var(--focus-ring-width, 2px) solid
    var(--focus-ring-color, var(--color-border-default-focus));
  outline-offset: 1px;
}
.bcn-atl__meta {
  align-items: center;
  gap: var(--spacing-200);
  min-width: 0;
  color: var(--color-content-default-secondary);
  font-size: 13px;
  display: flex;
}
.bcn-atl__code {
  flex-shrink: 0;
  display: inline-flex;
}
.bcn-atl__status {
  text-overflow: ellipsis;
  white-space: nowrap;
  overflow: hidden;
}
.bcn-atl__track {
  position: relative;
}
.bcn-atl__mark {
  top: calc(50% - var(--atl-mark-size) / 2);
  left: calc(var(--x) * var(--atl-day) - var(--atl-mark-size) / 2 + var(--atl-day) / 2);
  z-index: 2;
  width: var(--atl-mark-size);
  height: var(--atl-mark-size);
  border-radius: var(--radius-full);
  background: var(--atl-tone);
